constexpr const char* kinds[]={"sales","sellers","products","payments","cancellations","stock","low-stock","movements","cash","cash-sessions","receivables","payables"};
constexpr const char* captions[]={"Vendas no período","Vendas por vendedor","Produtos mais vendidos","Vendas por pagamento","Cancelamentos","Estoque atual","Estoque baixo","Histórico de estoque","Movimentações de caixa","Resumo dos caixas","Contas a receber","Contas a pagar"};
struct Row {char label[1700];};
struct State {unsigned serial,count,next,total,offset;bool busy,has_next;Row rows[8];char message[350],summary[4096],revision[65];};
struct Command {unsigned generation,kind,offset;bool open,inactive;char from[24],to[24],operator_id[24],product_id[24];};
struct Workspace {State state,draw,working;Command command,last;char response[16385],permissions[2048];};
Workspace* w;SemaphoreHandle_t mutex;QueueHandle_t queue;std::atomic<unsigned> generation{0};std::atomic<bool> visible{false};unsigned drawn;
lv_obj_t *root,*title,*notice,*selector,*from,*to,*operator_id,*product_id,*open_only,*inactive,*summary_panel,*summary,*list,*rows[8],*buttons[4],*keyboard;
lv_group_t* group;void(*home_callback)();
const char* text(cJSON* data,const char* key){auto* v=cJSON_GetObjectItemCaseSensitive(data,key);return cJSON_IsString(v)?v->valuestring:"";}
int number(cJSON* data,const char* key){auto* v=cJSON_GetObjectItemCaseSensitive(data,key);return cJSON_IsNumber(v)?v->valueint:0;}
void publish(const Command& cmd,const char* msg){xSemaphoreTake(mutex,portMAX_DELAY);if(cmd.generation==generation){w->working.busy=false;snprintf(w->working.message,sizeof(w->working.message),"%s",msg);w->working.serial=w->state.serial+1;w->state=w->working;}xSemaphoreGive(mutex);}
void enqueue(unsigned offset=0){if(!visible)return;Command cmd{};cmd.generation=generation;cmd.kind=lv_dropdown_get_selected(selector);cmd.offset=offset;cmd.open=lv_obj_has_state(open_only,LV_STATE_CHECKED);cmd.inactive=lv_obj_has_state(inactive,LV_STATE_CHECKED);snprintf(cmd.from,sizeof(cmd.from),"%s",lv_textarea_get_text(from));snprintf(cmd.to,sizeof(cmd.to),"%s",lv_textarea_get_text(to));snprintf(cmd.operator_id,sizeof(cmd.operator_id),"%s",lv_textarea_get_text(operator_id));snprintf(cmd.product_id,sizeof(cmd.product_id),"%s",lv_textarea_get_text(product_id));xSemaphoreTake(mutex,portMAX_DELAY);if(!w->state.busy&&xQueueSend(queue,&cmd,0)==pdTRUE){w->state.busy=true;++w->state.serial;snprintf(w->state.message,sizeof(w->state.message),"Consultando relatório...");}xSemaphoreGive(mutex);}
void keyboard_target(lv_event_t* e){lv_keyboard_set_textarea(keyboard,lv_event_get_target_obj(e));if(lv_event_get_code(e)==LV_EVENT_CLICKED)lv_obj_remove_flag(keyboard,LV_OBJ_FLAG_HIDDEN);}
void key_event(lv_event_t* e){auto key=lv_event_get_key(e);if(key==LV_KEY_ESC){if(!lv_obj_has_flag(keyboard,LV_OBJ_FLAG_HIDDEN))lv_obj_add_flag(keyboard,LV_OBJ_FLAG_HIDDEN);else{reports_hide();home_callback();}}else if(key==LV_KEY_UP)lv_group_focus_prev(group);else if(key==LV_KEY_DOWN)lv_group_focus_next(group);}
void click(lv_event_t* e){unsigned index=reinterpret_cast<uintptr_t>(lv_event_get_user_data(e));if(index==3){reports_hide();home_callback();return;}if(!w->draw.busy)enqueue(index==1?w->draw.next:0);}
void selector_changed(lv_event_t*){unsigned kind=lv_dropdown_get_selected(selector);if(kind>=12)return;bool stock=kind==5||kind==6;if(stock){lv_textarea_set_text(from,"");lv_textarea_set_text(to,"");}bool accounts=kind>=10;bool products=stock||kind==2||kind==7;for(auto* input:{from,to}){if(stock)lv_obj_add_state(input,LV_STATE_DISABLED);else lv_obj_remove_state(input,LV_STATE_DISABLED);}if(stock||accounts){lv_textarea_set_text(operator_id,"");lv_obj_add_state(operator_id,LV_STATE_DISABLED);}else lv_obj_remove_state(operator_id,LV_STATE_DISABLED);if(!products){lv_textarea_set_text(product_id,"");lv_obj_add_state(product_id,LV_STATE_DISABLED);}else lv_obj_remove_state(product_id,LV_STATE_DISABLED);if(accounts)lv_obj_remove_state(open_only,LV_STATE_DISABLED);else{lv_obj_remove_state(open_only,LV_STATE_CHECKED);lv_obj_add_state(open_only,LV_STATE_DISABLED);}if(stock)lv_obj_remove_state(inactive,LV_STATE_DISABLED);else{lv_obj_remove_state(inactive,LV_STATE_CHECKED);lv_obj_add_state(inactive,LV_STATE_DISABLED);}}
void render(lv_timer_t*){if(!visible)return;xSemaphoreTake(mutex,portMAX_DELAY);w->draw=w->state;xSemaphoreGive(mutex);auto& s=w->draw;if(s.serial==drawn)return;drawn=s.serial;lv_label_set_text(notice,s.message);lv_label_set_text(summary,s.summary);lv_group_remove_all_objs(group);lv_group_set_default(group);for(auto* indev=lv_indev_get_next(nullptr);indev;indev=lv_indev_get_next(indev))if(lv_indev_get_type(indev)==LV_INDEV_TYPE_KEYPAD)lv_indev_set_group(indev,group);for(auto* object:{selector,from,to,operator_id,product_id,open_only,inactive})lv_group_add_obj(group,object);int row_y=0;for(unsigned i=0;i<8;++i){if(i<s.count){lv_obj_remove_flag(rows[i],LV_OBJ_FLAG_HIDDEN);lv_label_set_text(lv_obj_get_child(rows[i],0),s.rows[i].label);lv_obj_set_pos(rows[i],0,row_y);lv_obj_set_height(rows[i],LV_SIZE_CONTENT);lv_obj_update_layout(rows[i]);row_y+=lv_obj_get_height(rows[i])+8;lv_group_add_obj(group,rows[i]);}else lv_obj_add_flag(rows[i],LV_OBJ_FLAG_HIDDEN);}for(unsigned i=0;i<4;++i){lv_group_add_obj(group,buttons[i]);if((s.busy&&i!=3)||(i==1&&!s.has_next))lv_obj_add_state(buttons[i],LV_STATE_DISABLED);else lv_obj_remove_state(buttons[i],LV_STATE_DISABLED);}if(s.busy)lv_obj_add_flag(keyboard,LV_OBJ_FLAG_HIDDEN);}
const char* label(const char* key){if(!strcmp(key,"sales"))return "Vendas";if(!strcmp(key,"gross"))return "Bruto R$";if(!strcmp(key,"discount"))return "Descontos R$";if(!strcmp(key,"total"))return "Total R$";if(!strcmp(key,"products"))return "Produtos";if(!strcmp(key,"quantity"))return "Quantidade";if(!strcmp(key,"movements"))return "Movimentos";if(!strcmp(key,"cancellations"))return "Cancelamentos";if(!strcmp(key,"inflows"))return "Entradas R$";if(!strcmp(key,"outflows"))return "Saídas R$";if(!strcmp(key,"cash_net"))return "Variação em dinheiro R$";if(!strcmp(key,"sessions"))return "Caixas";if(!strcmp(key,"closed"))return "Fechados";if(!strcmp(key,"opening"))return "Fundos iniciais R$";if(!strcmp(key,"closed_expected"))return "Esperado dos fechados R$";if(!strcmp(key,"closed_counted"))return "Contado dos fechados R$";if(!strcmp(key,"closed_difference"))return "Diferença dos fechados R$";if(!strcmp(key,"accounts"))return "Contas";if(!strcmp(key,"original"))return "Original R$";if(!strcmp(key,"paid"))return "Baixado R$";if(!strcmp(key,"remaining"))return "Saldo R$";return nullptr;}
const char* translate(const char* value){if(!strcmp(value,"cash"))return "Dinheiro";if(!strcmp(value,"pix"))return "Pix";if(!strcmp(value,"debit"))return "Débito";if(!strcmp(value,"credit"))return "Crédito";if(!strcmp(value,"transfer"))return "Transferência";if(!strcmp(value,"other"))return "Outros";if(!strcmp(value,"sale"))return "Venda";if(!strcmp(value,"sale_reversal"))return "Estorno gerencial";if(!strcmp(value,"deposit"))return "Suprimento";if(!strcmp(value,"withdraw"))return "Sangria";if(!strcmp(value,"settlement"))return "Baixa";if(!strcmp(value,"open"))return "Aberto";if(!strcmp(value,"closed"))return "Fechado";if(!strcmp(value,"inventory_entry"))return "Entrada";if(!strcmp(value,"inventory_exit"))return "Saída";if(!strcmp(value,"inventory_adjustment"))return "Contagem";if(!strcmp(value,"opening"))return "Saldo inicial";if(!strcmp(value,"cancellation"))return "Cancelamento";return value;}
