void reports_create(lv_display_t* display,void(*home)()){
    void* memory=heap_caps_calloc(1,sizeof(Workspace),MALLOC_CAP_SPIRAM|MALLOC_CAP_8BIT);if(!memory){ESP_LOGE("reports","PSRAM indisponível");return;}w=new(memory)Workspace{};mutex=xSemaphoreCreateMutex();auto* storage=static_cast<uint8_t*>(heap_caps_malloc(sizeof(Command),MALLOC_CAP_SPIRAM|MALLOC_CAP_8BIT));static StaticQueue_t control;queue=xQueueCreateStatic(1,sizeof(Command),storage,&control);home_callback=home;group=lv_group_create();
    root=lv_obj_create(lv_display_get_screen_active(display));lv_obj_set_size(root,1280,720);lv_obj_set_style_pad_all(root,10,0);lv_obj_set_style_text_font(root,&erp_font_pt_20,0);lv_obj_remove_flag(root,LV_OBJ_FLAG_SCROLLABLE);title=lv_label_create(root);lv_obj_set_pos(title,8,4);lv_obj_set_style_text_font(title,&erp_font_pt_28,0);lv_label_set_text(title,"Relatórios | Consultas gerenciais");notice=lv_label_create(root);lv_obj_set_pos(notice,8,45);lv_obj_set_width(notice,1200);lv_label_set_long_mode(notice,LV_LABEL_LONG_DOT);
    selector=lv_dropdown_create(root);lv_obj_set_pos(selector,8,96);lv_obj_set_size(selector,430,48);lv_dropdown_set_options(selector,"Vendas no período\nVendas por vendedor\nProdutos mais vendidos\nVendas por pagamento\nCancelamentos\nEstoque atual\nEstoque baixo\nHistórico de estoque\nMovimentações de caixa\nResumo dos caixas\nContas a receber\nContas a pagar");lv_obj_add_event_cb(selector,selector_changed,LV_EVENT_VALUE_CHANGED,nullptr);lv_obj_add_event_cb(selector,key_event,LV_EVENT_KEY,nullptr);
    from=lv_textarea_create(root);to=lv_textarea_create(root);operator_id=lv_textarea_create(root);product_id=lv_textarea_create(root);unsigned i=0;for(auto* object:{from,to,operator_id,product_id}){lv_obj_set_pos(object,i<2?460+(i%2)*385:8+(i%2)*310,i<2?96:166);lv_obj_set_size(object,i<2?365:290,48);lv_textarea_set_one_line(object,true);lv_textarea_set_max_length(object,10);lv_textarea_set_placeholder_text(object,i==0?"Desde AAAA-MM-DD":i==1?"Até AAAA-MM-DD":i==2?"ID operador (opcional)":"ID produto (opcional)");lv_obj_add_event_cb(object,keyboard_target,LV_EVENT_FOCUSED,nullptr);lv_obj_add_event_cb(object,keyboard_target,LV_EVENT_CLICKED,nullptr);lv_obj_add_event_cb(object,key_event,LV_EVENT_KEY,nullptr);++i;}
    open_only=lv_checkbox_create(root);lv_obj_set_pos(open_only,640,177);lv_checkbox_set_text(open_only,"Contas em aberto");inactive=lv_checkbox_create(root);lv_obj_set_pos(inactive,950,177);lv_checkbox_set_text(inactive,"Mostrar inativos");
    summary_panel=lv_obj_create(root);lv_obj_set_pos(summary_panel,8,232);lv_obj_set_size(summary_panel,1220,130);summary=lv_label_create(summary_panel);lv_obj_set_width(summary,1165);lv_label_set_long_mode(summary,LV_LABEL_LONG_WRAP);
    list=lv_obj_create(root);lv_obj_set_pos(list,8,374);lv_obj_set_size(list,1220,226);for(unsigned j=0;j<8;++j){rows[j]=lv_button_create(list);lv_obj_set_pos(rows[j],0,j*250);lv_obj_set_size(rows[j],1165,244);auto* value=lv_label_create(rows[j]);lv_obj_set_width(value,1120);lv_label_set_long_mode(value,LV_LABEL_LONG_WRAP);lv_obj_add_event_cb(rows[j],key_event,LV_EVENT_KEY,nullptr);}
    const char* names[]={"Primeira página","Próxima","Consultar / atualizar","Menu"};for(unsigned j=0;j<4;++j){buttons[j]=lv_button_create(root);lv_obj_set_pos(buttons[j],8+j*306,622);lv_obj_set_size(buttons[j],294,50);auto* value=lv_label_create(buttons[j]);lv_label_set_text(value,names[j]);lv_obj_center(value);lv_obj_add_event_cb(buttons[j],click,LV_EVENT_CLICKED,reinterpret_cast<void*>(static_cast<uintptr_t>(j)));lv_obj_add_event_cb(buttons[j],key_event,LV_EVENT_KEY,nullptr);}
    keyboard=lv_keyboard_create(root);lv_obj_set_pos(keyboard,8,450);lv_obj_set_size(keyboard,1220,240);for(auto event:{LV_EVENT_READY,LV_EVENT_CANCEL})lv_obj_add_event_cb(keyboard,[](lv_event_t*){lv_obj_add_flag(keyboard,LV_OBJ_FLAG_HIDDEN);},event,nullptr);lv_obj_add_flag(keyboard,LV_OBJ_FLAG_HIDDEN);lv_obj_add_flag(root,LV_OBJ_FLAG_HIDDEN);lv_timer_create(render,100,nullptr);
}
void reports_hide(){if(!w)return;visible=false;++generation;xQueueReset(queue);lv_obj_add_flag(root,LV_OBJ_FLAG_HIDDEN);xSemaphoreTake(mutex,portMAX_DELAY);memset(&w->state,0,sizeof(w->state));xSemaphoreGive(mutex);memset(&w->draw,0,sizeof(w->draw));for(auto* input:{from,to,operator_id,product_id})lv_textarea_set_text(input,"");lv_label_set_text(summary,"");lv_label_set_text(notice,"");for(auto* row:rows)lv_label_set_text(lv_obj_get_child(row,0),"");}
void reports_open(const char* permissions,bool light){if(!w)return;snprintf(w->permissions,sizeof(w->permissions),"%s",permissions);drawn=0;auto fg=lv_color_hex(light?0x0f172a:0xf8fafc),bg=lv_color_hex(light?0xe2e8f0:0x334155);lv_obj_set_style_bg_color(root,lv_color_hex(light?0xf1f5f9:0x111827),0);lv_obj_set_style_text_color(root,fg,0);for(auto* object:{list,summary_panel})lv_obj_set_style_bg_color(object,lv_color_hex(light?0xffffff:0x1e293b),0);for(auto* object:{selector,from,to,operator_id,product_id}){lv_obj_set_style_bg_color(object,bg,0);lv_obj_set_style_text_color(object,fg,0);}auto* drop=lv_dropdown_get_list(selector);if(drop){lv_obj_set_style_bg_color(drop,bg,0);lv_obj_set_style_text_color(drop,fg,0);lv_obj_set_style_text_font(drop,&erp_font_pt_20,0);}for(auto* object:rows){lv_obj_set_style_bg_color(object,bg,0);lv_obj_set_style_text_color(object,fg,0);}for(auto* object:buttons){lv_obj_set_style_bg_color(object,bg,0);lv_obj_set_style_text_color(object,fg,0);}lv_obj_set_style_bg_color(keyboard,bg,LV_PART_ITEMS);lv_obj_set_style_text_color(keyboard,fg,LV_PART_ITEMS);lv_dropdown_set_selected(selector,has_module_permission(permissions,"reports.financial")?0:5);selector_changed(nullptr);visible=true;lv_obj_remove_flag(root,LV_OBJ_FLAG_HIDDEN);enqueue();render(nullptr);}

bool reports_handle_next(const char* permissions,bool online,ProductTransport transport){if(!w||xQueueReceive(queue,&w->command,0)!=pdTRUE)return false;const auto& cmd=w->command;if(cmd.generation!=generation)return true;xSemaphoreTake(mutex,portMAX_DELAY);w->working=w->state;xSemaphoreGive(mutex);auto& s=w->working;auto done=[&](const char* message){publish(cmd,message);return true;};if(!has_module_permission(permissions,"reports.read"))return done("Seu perfil não permite consultar relatórios.");if(cmd.kind>=12)return done("Selecione um relatório válido.");if(cmd.kind!=5&&cmd.kind!=6&&cmd.kind!=7&&!has_module_permission(permissions,"reports.financial"))return done("Seu perfil não permite relatórios financeiros.");if(!online)return done("Sem conexão. Relatórios precisam da API disponível.");if((cmd.from[0]&&!valid_financial_date(cmd.from))||(cmd.to[0]&&!valid_financial_date(cmd.to)))return done("Confira as datas: AAAA-MM-DD. Campos vazios consultam o dia atual.");
    auto identity=[](const char* value){if(!*value)return true;for(const char* p=value;*p;++p)if(*p<'0'||*p>'9')return false;return strtoull(value,nullptr,10)>0&&strtoull(value,nullptr,10)<=2147483647ULL;};if(!identity(cmd.operator_id)||!identity(cmd.product_id))return done("Informe IDs numéricos positivos, ou deixe os campos vazios.");
    if(cmd.offset&&(cmd.kind!=w->last.kind||strcmp(cmd.from,w->last.from)||strcmp(cmd.to,w->last.to)||strcmp(cmd.operator_id,w->last.operator_id)||strcmp(cmd.product_id,w->last.product_id)||cmd.open!=w->last.open||cmd.inactive!=w->last.inactive))return done("Filtros alterados. Consulte a primeira página.");
    std::string url=std::string("/api/v1/reports/")+kinds[cmd.kind]+"?limit=8&offset="+std::to_string(cmd.offset)+"&only_open="+(cmd.open?"true":"false")+"&include_inactive="+(cmd.inactive?"true":"false");if(cmd.from[0])url+="&from_date="+std::string(cmd.from);if(cmd.to[0])url+="&to_date="+std::string(cmd.to);if(cmd.operator_id[0])url+="&operator_id="+std::string(cmd.operator_id);if(cmd.product_id[0])url+="&product_id="+std::string(cmd.product_id);if(cmd.offset)url+="&revision="+std::string(s.revision);
    memset(w->response,0,sizeof(w->response));int code=transport("GET",url.c_str(),nullptr,w->response,sizeof(w->response));auto* data=cJSON_Parse(w->response);if(code!=200){std::string message=text(cJSON_GetObjectItemCaseSensitive(data,"error"),"message");if(message.empty())message=code<=0?"Sem resposta da API. Confira rede e servidor.":"Não foi possível consultar o relatório.";s.has_next=false;s.count=0;s.summary[0]=0;cJSON_Delete(data);return done(message.c_str());}if(strcmp(text(data,"kind"),kinds[cmd.kind])||strlen(text(data,"revision"))!=64||!cJSON_IsArray(cJSON_GetObjectItemCaseSensitive(data,"rows"))){cJSON_Delete(data);return done("Resposta de relatório inválida.");}
    s.count=0;s.total=number(data,"rows_total");s.offset=cmd.offset;auto* next=cJSON_GetObjectItemCaseSensitive(data,"next_offset");s.has_next=cJSON_IsNumber(next);s.next=s.has_next?next->valueint:0;snprintf(s.revision,sizeof(s.revision),"%s",text(data,"revision"));snprintf(s.summary,sizeof(s.summary),"%s | %s a %s | Horário de Cuiabá\nRegistros: %u | Página %u\n",captions[cmd.kind],text(data,"from_date"),text(data,"to_date"),s.total,cmd.offset/8+1);auto* totals=cJSON_GetObjectItemCaseSensitive(data,"summary");cJSON* value; cJSON_ArrayForEach(value,totals){const char* name=label(value->string);if(!name)continue;char numeric[48];snprintf(numeric,sizeof(numeric),"%.0f",value->valuedouble);size_t used=strlen(s.summary);snprintf(s.summary+used,sizeof(s.summary)-used,"%s: %s | ",name,cJSON_IsString(value)?value->valuestring:numeric);}auto* columns=cJSON_GetObjectItemCaseSensitive(data,"columns");auto* values=cJSON_GetObjectItemCaseSensitive(data,"rows");cJSON* row;cJSON_ArrayForEach(row,values){if(s.count==8)break;auto& output=s.rows[s.count++];output.label[0]=0;unsigned index=0;cJSON* cell;cJSON_ArrayForEach(cell,row){auto* col=cJSON_GetArrayItem(columns,index++);if(!cJSON_IsString(col)||!cJSON_IsString(cell))continue;size_t used=strlen(output.label);snprintf(output.label+used,sizeof(output.label)-used,"%s: %s\n",col->valuestring,(!strcmp(col->valuestring,"Forma")||!strcmp(col->valuestring,"Tipo")||!strcmp(col->valuestring,"Situação"))?translate(cell->valuestring):cell->valuestring);}}w->last=cmd;cJSON_Delete(data);return done(cmd.kind==5||cmd.kind==6?"Saldo ATUAL por unidade. As datas não reconstituem estoque histórico.":cmd.kind>=10?"Período por vencimento. Baixas e saldo refletem a situação atual.":"Totais do período completo; a lista está paginada. Datas dos registros no horário de Cuiabá.");
}
